import{_ as a,C as e,o as n,c as p,H as o,Q as t}from"./chunks/framework.be8d362c.js";const E=JSON.parse('{"title":"改善工具配置简单操作运维","description":"记录分享下自己日常工作中使用的到一些工具如ssh、tmux、terminator等按个人习惯对其做了相应配置以保持简洁傻瓜式方便。","frontmatter":{"title":"改善工具配置简单操作运维","date":"2012-10-28 00:07","tags":["ssh","tmux","terminator"],"description":"记录分享下自己日常工作中使用的到一些工具如ssh、tmux、terminator等按个人习惯对其做了相应配置以保持简洁傻瓜式方便。"},"headers":[],"relativePath":"posts/keep-simple-stupid-with-tools.md","filePath":"posts/keep-simple-stupid-with-tools.md"}'),l={name:"posts/keep-simple-stupid-with-tools.md"},r=t(`<p>记录分享下自己日常工作中使用的到一些工具如ssh、tmux、terminator等按个人习惯对其做了相应配置以保持简洁傻瓜式方便。</p><p>其中涉及到的配置文件主要有</p><ul><li>ssh的用户配置文件$HOME/.ssh/config</li><li>tmux的$HOME/.tmux.conf</li><li>terminator终端工具配置文件$HOME/.config/terminator/config</li></ul><p>以及可能涉及到$HOME/.bashrc等</p><h5 id="修改配置-home-ssh-config让你生活更简单-省心省事" tabindex="-1">修改配置$HOME/.ssh/config让你生活更简单（省心省事） <a class="header-anchor" href="#修改配置-home-ssh-config让你生活更简单-省心省事" aria-label="Permalink to &quot;修改配置$HOME/.ssh/config让你生活更简单（省心省事）&quot;">​</a></h5><p>通常默认情况我们使用以下方式ssh连接：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">$ssh username@hostname/ip -p port</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">$ssh username@hostname/ip -p port</span></span></code></pre></div><p>机器一多的话每次都要输入一串便会令人感觉繁琐，如果再加上实现没有使用ssh-copy-id功能采用公密钥认证方式登陆的话，每次都还要手动输入密码的话就更浪费时间。</p><p>改善后，很多人或许会想到结合$HOME/.bashrc的别名alias功能，在此配置文件添加相应的别名如下：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">alias</span><span style="color:#E1E4E8;"> name</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&#39;ssh username@hostname/ip -p port&#39;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">alias</span><span style="color:#24292E;"> name</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&#39;ssh username@hostname/ip -p port&#39;</span></span></code></pre></div><p>其实这里如果知道<code>ssh_config</code>这东西的话，可以直接修改$HOME/.ssh/config如下:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">host</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">name</span></span>
<span class="line"><span style="color:#B392F0;">hostname</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">hostip</span></span>
<span class="line"><span style="color:#B392F0;">user</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">username</span></span>
<span class="line"><span style="color:#B392F0;">port</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">port</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">host</span><span style="color:#24292E;"> </span><span style="color:#032F62;">name</span></span>
<span class="line"><span style="color:#6F42C1;">hostname</span><span style="color:#24292E;"> </span><span style="color:#032F62;">hostip</span></span>
<span class="line"><span style="color:#6F42C1;">user</span><span style="color:#24292E;"> </span><span style="color:#032F62;">username</span></span>
<span class="line"><span style="color:#6F42C1;">port</span><span style="color:#24292E;"> </span><span style="color:#032F62;">port</span></span></code></pre></div><p>如此一来，你只需要使用命令<code>ssh name</code>连接管理。或许你也发现这样一来ssh还是需要每次重复输入，是的，所以可以结合前面的$HOME/.bashrc别名进一步处理。</p><p>单独创建一个ssh连接的别名文件为：$HOME/.ssh/bashrc 内容类似于：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">alias</span><span style="color:#E1E4E8;"> name</span><span style="color:#F97583;">=</span><span style="color:#9ECBFF;">&#39;ssh name&#39;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">alias</span><span style="color:#24292E;"> name</span><span style="color:#D73A49;">=</span><span style="color:#032F62;">&#39;ssh name&#39;</span></span></code></pre></div><p>然后将此文件加载到用户目录下的bashrc配置文件结尾，编辑$HOME/.bashrc后，执行source $HOME/.bashrc使其生效：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#79B8FF;">source</span><span style="color:#E1E4E8;"> $HOME</span><span style="color:#9ECBFF;">/.ssh/bashrc</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#005CC5;">source</span><span style="color:#24292E;"> $HOME</span><span style="color:#032F62;">/.ssh/bashrc</span></span></code></pre></div><p>这样以后就只需输入相应的name（如个人这里取地区名称简写加ip末尾为name）回车执行即可。</p><h5 id="再结合一些小工具如tmux-screen的可以更方便管理操作" tabindex="-1">再结合一些小工具如tmux/screen的可以更方便管理操作 <a class="header-anchor" href="#再结合一些小工具如tmux-screen的可以更方便管理操作" aria-label="Permalink to &quot;再结合一些小工具如tmux/screen的可以更方便管理操作&quot;">​</a></h5><p>关于这些小工具想必都比较清楚，这里记录个人下使用的配置文件：<a href="https://gist.github.com/3950948" target="_blank" rel="noreferrer">$HOME/.tmux.conf</a></p><h5 id="终端建议改用terminator-至于原因个人觉得其支持的功能更强大-特别其group功能相当的方便。" tabindex="-1">终端建议改用Terminator，至于原因个人觉得其支持的功能更强大，特别其group功能相当的方便。 <a class="header-anchor" href="#终端建议改用terminator-至于原因个人觉得其支持的功能更强大-特别其group功能相当的方便。" aria-label="Permalink to &quot;终端建议改用Terminator，至于原因个人觉得其支持的功能更强大，特别其group功能相当的方便。&quot;">​</a></h5><p>这个是自己对Terminator做了写改动后的配置文件:<a href="https://gist.github.com/3950895" target="_blank" rel="noreferrer">$HOME/.config/terminator/config</a></p>`,22);function c(i,h,d,m,u,y){const s=e("Comment");return n(),p("div",null,[r,o(s)])}const b=a(l,[["render",c]]);export{E as __pageData,b as default};
